_CACHE: dict[str, str] = {}

def resolve(host: str) -> str:
    # Process-wide cache is shared because DNS answers are identical across
    # threads and the TTL logic lives in refresh(); a per-call cache would
    # re-query our rate-limited resolver on every request.
    if host not in _CACHE:
        _CACHE[host] = _slow_lookup(host)
    return _CACHE[host]

